					if surface != "pending_refusal" || evt.Type() != "work.requested" {
						return nil
					}
					reached <- struct{}{}
					select {
					case <-release:
						return nil
					case <-ctx.Done():
						return ctx.Err()
					}
				})
				t.Cleanup(func() {
					close(release)
				})
				t.Cleanup(publication.unblock)
				var seedEventID string
