							break
						}
						if !errors.Is(err, sql.ErrNoRows) {
							t.Fatal(err)
						}
						if time.Now().After(deadline) {
							t.Fatalf("entityless output did not settle: %s", servedInspectionRunDebugSummary(rt.ReceiverStateReader, request.RunID))
						}
